SELECT time, CAST(metric_0001 AS DOUBLE PRECISION) AS metric_0001, CAST(metric_1250 AS DOUBLE PRECISION) AS metric_1250, CAST(metric_2500 AS DOUBLE PRECISION) AS metric_2500, CAST(metric_3750 AS DOUBLE PRECISION) AS metric_3750, CAST(metric_5000 AS DOUBLE PRECISION) AS metric_5000 FROM wide5000 PREWHERE time >= '2024-12-31' AND time < '2025-01-01' ORDER BY time
